python3 - <<'EOF'
import json
inv = json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
def find_tap(x, name=''):
    if isinstance(x, dict):
        for k,v in x.items():
            if k in ('tap_records','tap_role_totals'):
                print(name + k, "->", type(v).__name__, len(v) if hasattr(v,'__len__') else '')
            find_tap(v, name + (k+':'))
    elif isinstance(x, list):
        for i,v in enumerate(x[:3]):
            find_tap(v, name + f"[{i}]:")
find_tap(inv, '')
# look at one step of baseline-r0
for run in inv['runs']:
    if run['run_id']=='inventory-baseline-r0':
        s = run['steps']['0']
        print("\nstep0 keys:", list(s.keys()))
        for k,v in s.items():
            if 'tap' in k.lower() or 'record' in k.lower():
                print(k, "=", v if len(str(v))<400 else str(v)[:400])
        # print all keys with small values
EOF

